package dev.oreslang;

import dev.oreslang.compiler.OresCompiler;
import dev.oreslang.parser.Parser;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Compiler admission for the declaration-only output generated by
 * ORESoftware/ores-clients-core PR #12. These tests do not claim JSON
 * Schema/TJSV runtime or serialization conformance.
 */
final class PolyglotClientContractAdmissionTest {
    // Match the Rust renderer's canonical module contract, not an interface
    // declaration with Unknown payload types (which is a different semantic API).
    private static final String GENERATED_HEADER = """
            // Declaration-only: String args/results contain JSON wire text.
            define contract ClientContract as
              fnc get_status(String request_id) => String;
              fnc get_items(String page, String page_size) => String;
            end
            """;

    private static final String IMPLEMENTATION = """
            define module client conforms ClientContract as
              pub fnc get_status(String request_id): String {
                return request_id;
              }
              pub fnc get_items(String page, String page_size): String {
                return page;
              }
            end
            pub routine main(): void {
              return;
            }
            """;

    @Test
    void generatedModuleContractParsesAndTypeChecks() {
        assertDoesNotThrow(() -> Parser.parse(GENERATED_HEADER));
        assertDoesNotThrow(() -> OresCompiler.parseAndTypeCheck(GENERATED_HEADER));
        assertDoesNotThrow(() -> OresCompiler.parseAndTypeCheck(GENERATED_HEADER + IMPLEMENTATION));
    }

    @Test
    void refusesImplementationThatViolatesGeneratedContract() {
        String bad = """
                define module client conforms ClientContract as
                  pub fnc get_status(String request_id): String {
                    return request_id;
                  }
                end
                """;
        assertThrows(IllegalArgumentException.class,
                () -> OresCompiler.parseAndTypeCheck(GENERATED_HEADER + bad));
    }

    @Test
    void refusesInjectedOperationAndMalformedMemberSignature() {
        String injected = """
                define contract ClientContract as
                  fnc get_status(String request_id); pub fnc hijack(): String;
                end
                """;
        assertThrows(IllegalArgumentException.class, () -> Parser.parse(injected));

        String wrongReturnSeparator = """
                define contract ClientContract as
                  fnc get_status(String request_id): String;
                end
                """;
        assertThrows(IllegalArgumentException.class, () -> Parser.parse(wrongReturnSeparator));
    }

    @Test
    void moduleContractIsNotClassInterface() {
        String invalid = """
                define contract ClientContract as
                  fnc get_status(String request_id) => String;
                end
                define class Client implements ClientContract as
                  get_status(String request_id): String { return request_id; }
                end
                """;
        assertThrows(IllegalArgumentException.class,
                () -> OresCompiler.parseAndTypeCheck(invalid));
    }
}
